// Mock per-engineer stats - swap for Metabase / Plain exports in production
const SLACK_WEBHOOK = 'https://hooks.slack.com/services/REPLACE-ME'; // incoming webhook for #support-metrics
return [{ json: { slackWebhook: SLACK_WEBHOOK, week: new Date().toISOString().slice(0, 10), stats: [
  { name: 'Dana', resolved: 58, frMedianMin: 38, csat: 4.7, lastWeekResolved: 51 },
  { name: 'Marco', resolved: 49, frMedianMin: 51, csat: 4.5, lastWeekResolved: 40 },
  { name: 'Lena', resolved: 44, frMedianMin: 45, csat: 4.8, lastWeekResolved: 46 },
  { name: 'Priya', resolved: 71, frMedianMin: 35, csat: 4.6, lastWeekResolved: 69 },
  { name: 'Sam', resolved: 22, frMedianMin: 88, csat: 4.1, lastWeekResolved: 35 }
] } }];

const { stats, week, slackWebhook } = $input.first().json;
const scored = stats.map(s => ({ ...s, score: Math.round(s.resolved * 0.4 + (100 - Math.min(s.frMedianMin, 100)) * 0.3 + s.csat * 20 * 0.3), delta: s.resolved - s.lastWeekResolved }));
scored.sort((a, b) => b.score - a.score);
const top = scored[0];
const improved = [...scored].sort((a, b) => b.delta - a.delta)[0];
const fastest = [...scored].sort((a, b) => a.frMedianMin - b.frMedianMin)[0];
const totals = { resolved: stats.reduce((x, s) => x + s.resolved, 0), csat: (stats.reduce((x, s) => x + s.csat, 0) / stats.length).toFixed(2) };
let publicText = ':trophy: Support week in review (' + week + ')

' +
  'Team: ' + totals.resolved + ' tickets resolved, avg CSAT ' + totals.csat + '

' +
  ':first_place_medal: Top performer: ' + top.name + ' (' + top.resolved + ' resolved, ' + top.frMedianMin + 'm median first response, CSAT ' + top.csat + ')
' +
  ':chart_with_upwards_trend: Most improved: ' + improved.name + ' (+' + improved.delta + ' vs last week)
' +
  ':zap: Fastest first response: ' + fastest.name + ' (' + fastest.frMedianMin + 'm median)

' +
  'Full leaderboard:
' + scored.map((s, i) => (i + 1) + '. ' + s.name + ' - score ' + s.score).join('
');
const flags = scored.filter(s => s.csat < 4.3 || s.frMedianMin > 75 || s.delta < -8);
let privateText = 'Lead-only coaching notes (' + week + '):

' + (flags.length ? flags.map(s => s.name + ': ' + [s.csat < 4.3 ? 'CSAT ' + s.csat : '', s.frMedianMin > 75 ? 'first response ' + s.frMedianMin + 'm' : '', s.delta < -8 ? 'volume down ' + s.delta : ''].filter(Boolean).join(', ') + '. Raise gently at the next 1:1; look for stuck tickets or PTO/burnout context first.').join('

') : 'No flags this week.') + '

Principle: praise in public, coach in private.';
return [{ json: { slackWebhook, publicText, privateText, week } }];
